import org.openpatch.scratch.*;

public class Diamond extends Sprite {
  public Diamond() {
    this.addCostume("gemBlue");
    this.setSize(40);
    this.setY(400);
  }

  public void run() {
    this.changeY(-5);
    if (this.isTouchingSprite(Basket.class)) {
      ((CatchStage) this.getStage()).addPoint();
      ((CatchStage) this.getStage()).addPoint();
      this.setY(400);
    }
    if (this.getY() < -200) {
      this.setY(400);
    }
  }
}
